const cameraDialog=document.createElement('dialog');
cameraDialog.id='cameraDialog';cameraDialog.className='work-dialog';
cameraDialog.style.cssText='width:min(880px,94vw);max-height:92vh;overflow:auto';document.body.append(cameraDialog);
cameraDialog.addEventListener('keydown',event=>event.stopPropagation());
let cameraSession=null;
const cameraCss=document.createElement('style');cameraCss.textContent='#cameraDialog .camera-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}#cameraDialog select{max-width:260px}#cameraDialog video{display:block;width:100%;height:min(32vh,290px);background:#020a16;object-fit:contain;border:1px solid #355078;border-radius:8px;margin:12px 0}#cameraDialog .camera-buttons{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}#cameraDialog button:disabled{opacity:.4;cursor:not-allowed}#cameraDialog .camera-live{color:#ffd164}#cameraDialog .camera-live.recording{color:#ff6979}#cameraDialog label:has(input[type=checkbox]){justify-content:flex-start;gap:10px}';document.head.append(cameraCss);
function cameraError(e){if(e.name==='NotAllowedError')return 'Permiso de cámara o micrófono denegado. Revisa Configuración de Windows → Privacidad → Cámara / Micrófono → aplicaciones de escritorio.';if(e.name==='NotFoundError')return 'No se encuentra la cámara o el micrófono seleccionado.';if(e.name==='NotReadableError')return 'No se puede abrir la cámara o el micrófono. Comprueba si otra aplicación lo está usando.';return e.message||String(e);}
cameraCss.textContent+='#cameraDialog .camera-grid label:not(:has(input[type=checkbox])){display:flex;flex-direction:column;align-items:stretch;gap:6px}#cameraDialog .camera-grid select,#cameraDialog .camera-grid input[type=number]{width:100%;max-width:100%;box-sizing:border-box}';
cameraCss.textContent+='#cameraDialog.screen-mode video{height:min(23vh,190px)}#cameraDialog.screen-mode .camera-grid{gap:8px 12px}#cameraDialog.screen-mode label{margin:6px 0}#cameraDialog.screen-mode p{margin:8px 0}';
async function cameraFileInfo(filePath){const video=document.createElement('video');video.preload='metadata';try{const url=await window.lqtacDesktop.mediaFileUrl(filePath);return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('No se pudo leer la duración del vídeo guardado')),15000);video.onloadedmetadata=()=>{clearTimeout(timer);if(Number.isFinite(video.duration)&&video.duration>0&&video.videoWidth)resolve({durationSeconds:video.duration,width:video.videoWidth,height:video.videoHeight});else reject(Error('La toma guardada no tiene una duración válida'));};video.onerror=()=>{clearTimeout(timer);reject(Error('No se puede abrir la toma guardada'));};video.src=url;});}finally{video.removeAttribute('src');video.load();}}
async function openCameraRecorder(mode='camera'){
  const isScreen=mode==='screen',captureLabel=isScreen?'Pantalla':'Cámara';
  if(cameraSession||exporting||historyBusy||document.querySelector('dialog[open]'))return;
  if(!window.lqtacDesktop?.cameraRecordingStart){toast('Abre el programa de escritorio actualizado para grabar cámara.');return;}
  cameraDialog.classList.toggle('screen-mode',isScreen);
  stopTimelinePlayback();
  const s={state:'idle',mode,stream:null,recorder:null,id:null,queue:Promise.resolve(),backlog:0,error:null,saved:null,inserted:false,hasAudio:false,started:0,timer:null,closed:false,previousInert:$('.workspace').inert,releaseExtra:null,audioLabel:'sin audio'};cameraSession=s;$('.workspace').inert=true;
  cameraDialog.innerHTML=`<h2>Grabar vídeo · cámara</h2>
  <div class="camera-grid"><label>Cámara<select id="cameraDevice"><option value="default">Cámara predeterminada</option></select></label><label>Calidad solicitada<select id="cameraQuality"><option value="720">1280 × 720 · 30 fps</option><option value="1080">1920 × 1080 · 30 fps</option><option value="480">640 × 480 · 30 fps</option></select></label><label><input id="cameraUseAudio" type="checkbox" checked> Grabar también micrófono</label><label>Micrófono<select id="cameraMicrophone"><option value="default">Micrófono predeterminado</option></select></label></div>
  <video id="cameraPreview" muted playsinline></video><p id="cameraLive" class="camera-live">Cámara desconectada</p>
  <div class="camera-buttons"><button id="cameraRefresh" type="button">Actualizar entradas</button><button id="cameraPrepare" type="button">Activar cámara</button><button id="cameraDisconnect" type="button" disabled>Desconectar</button></div>
  <div class="camera-grid"><label>Posición en proyecto (s)<input id="cameraPosition" type="number" min="0" max="604800" step="0.001"></label><label><input id="cameraAutoInsert" type="checkbox" checked> Insertar en pistas nuevas al terminar</label></div>
  <p>Vista previa silenciosa para evitar acoples. La resolución real depende de la cámara. Guarda en WebM (VP8 y, con micrófono, Opus). Puedes exportar después a MP4 desde el proyecto.</p>
  <div class="camera-buttons"><button id="cameraRecord" type="button" disabled>● Grabar vídeo…</button><button id="cameraStop" type="button" disabled>■ Detener y guardar</button><button id="cameraDiscard" type="button" disabled>Descartar toma</button><button id="cameraRetry" type="button" disabled>Guardar en otra ruta…</button></div>
  <p id="cameraStatus" role="status">Pulsa Activar cámara para preparar la vista previa. Aún no se graba.</p><p id="cameraSavedPath" style="overflow-wrap:anywhere"></p>
  <footer><button id="cameraInsert" type="button" disabled>Insertar toma guardada</button><button id="cameraClose" type="button">Cerrar</button></footer>`;
  if(isScreen){$('h2',cameraDialog).textContent='Grabar pantalla o ventana';$('#cameraDevice').parentElement.firstChild.textContent='Pantalla o ventana';$('#cameraDevice').replaceChildren(new Option('Pulsa Actualizar entradas',''));$('#cameraUseAudio').checked=false;$('#cameraQuality').value='1080';$('.camera-grid',cameraDialog).insertAdjacentHTML('beforeend','<label><input id="screenSystemAudio" type="checkbox"> Grabar audio del sistema</label><p>El audio del sistema incluye todo el sonido del equipo, también al capturar una ventana. Sistema + micrófono se mezclan en una pista de audio.</p>');$('#cameraPrepare').textContent='Preparar captura';$('#cameraStatus').textContent='Selecciona una pantalla o ventana y pulsa Preparar captura. La vista previa ya comparte esa fuente.';$('#cameraLive').textContent='Pantalla desconectada';const help=$$('.camera-grid ~ p',cameraDialog).find(p=>p.id==='');if(help)help.textContent='Vista previa silenciosa. Guarda WebM local y añade la toma al proyecto. Puedes minimizar LQTAC al grabar; vuelve a esta ventana para detener. Si capturas LQTAC o su pantalla se verá el editor dentro de la grabación.';}
  $('#cameraPosition').value=timelineTime;
  const status=text=>{if(!s.closed)$('#cameraStatus').textContent=text;};
  function update(){if(s.closed)return;const locked=!['idle','done'].includes(s.state);for(const id of ['cameraDevice','cameraQuality','cameraUseAudio','cameraRefresh','cameraPrepare',...(isScreen?['screenSystemAudio']:[])])$('#'+id).disabled=locked;$('#cameraMicrophone').disabled=locked||!$('#cameraUseAudio').checked;$('#cameraDisconnect').disabled=s.state!=='ready';$('#cameraRecord').disabled=s.state!=='ready';$('#cameraStop').disabled=s.state!=='recording';$('#cameraDiscard').disabled=!['recording','pending'].includes(s.state);$('#cameraRetry').disabled=s.state!=='pending';$('#cameraInsert').disabled=!s.saved||s.inserted||locked;$('#cameraPosition').disabled=locked;$('#cameraAutoInsert').disabled=locked;$('#cameraClose').disabled=['preparing','choosing','stopping','saving','closing'].includes(s.state);$('#cameraLive').classList.toggle('recording',s.state==='recording');if(!s.stream)$('#cameraLive').textContent=isScreen?'Pantalla y entradas de audio desconectadas':'Cámara y micrófono desconectados';}
  async function devices(){try{if(isScreen){const previous=$('#cameraDevice').value,sources=await window.lqtacDesktop.screenCaptureSources();if(s.closed)return;$('#cameraDevice').replaceChildren(...sources.map(source=>new Option((source.kind==='screen'?'Pantalla · ':'Ventana · ')+source.name,source.id)));if(sources.some(source=>source.id===previous))$('#cameraDevice').value=previous;}const all=await navigator.mediaDevices.enumerateDevices();if(s.closed)return;for(const [id,kind,label] of (isScreen?[['cameraMicrophone','audioinput','Micrófono']]:[['cameraDevice','videoinput','Cámara'],['cameraMicrophone','audioinput','Micrófono']])){const select=$('#'+id),previous=select.value;select.replaceChildren(new Option(label+' predeterminado','default'));all.filter(d=>d.kind===kind&&d.deviceId&&d.deviceId!=='default').forEach((d,i)=>select.append(new Option(d.label||label+' '+(i+1),d.deviceId)));if([...select.options].some(o=>o.value===previous))select.value=previous;}}catch(e){status(cameraError(e));}}
  function release(){clearInterval(s.timer);s.timer=null;const stream=s.stream;s.stream=null;stream?.getTracks().forEach(t=>{t.onended=null;t.stop();});s.releaseExtra?.();s.releaseExtra=null;$('#cameraPreview').srcObject=null;update();if(isScreen)$('#cameraLive').textContent='Pantalla y entradas de audio desconectadas';}
  function live(){if(!s.stream)return;const v=s.stream.getVideoTracks()[0].getSettings();const seconds=Math.floor((performance.now()-s.started)/1000);$('#cameraLive').textContent=(s.state==='recording'?'● GRABANDO · '+String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'):'● '+captureLabel+' activa · vista previa')+' · '+v.width+' × '+v.height+' · '+Math.round(v.frameRate||0)+' fps · '+(isScreen?s.audioLabel:s.hasAudio?'con micrófono':'sin audio');if(s.state==='recording'&&seconds>=7200)void stop();}
  async function prepare(){
    if(!['idle','done'].includes(s.state))return;s.state='preparing';update();status(isScreen?'Preparando fuente seleccionada…':'Abriendo cámara'+($('#cameraUseAudio').checked?' y micrófono':'')+'…');
    const preview=$('#cameraPreview');preview.pause();preview.removeAttribute('src');preview.controls=false;preview.muted=true;
    try{
      const device=$('#cameraDevice').value,mic=$('#cameraMicrophone').value,height=Number($('#cameraQuality').value),width=height===480?640:height===1080?1920:1280;let sourceTracks=[];
      if(isScreen){const capture=await LQTACScreenCapture.prepare({source:device,systemAudio:$('#screenSystemAudio').checked,microphone:$('#cameraUseAudio').checked,microphoneId:mic,height});s.stream=capture.stream;s.releaseExtra=capture.dispose;s.audioLabel=capture.audioLabel;sourceTracks=capture.sourceTracks;}
      else s.stream=await navigator.mediaDevices.getUserMedia({video:{...(device==='default'?{}:{deviceId:{exact:device}}),width:{ideal:width},height:{ideal:height},frameRate:{ideal:30,max:30}},audio:$('#cameraUseAudio').checked?{...(mic==='default'?{}:{deviceId:{exact:mic}}),echoCancellation:false,noiseSuppression:false,autoGainControl:false}:false});
      s.hasAudio=s.stream.getAudioTracks().length>0;preview.srcObject=s.stream;await preview.play();
      [...s.stream.getTracks(),...sourceTracks].forEach(t=>t.onended=()=>{if(s.state==='recording'){status('Fuente desconectada. Finalizando lo capturado…');void stop();}else if(s.state==='ready'){release();s.state='idle';update();status('La fuente se ha desconectado. Prepara de nuevo la captura.');}});
      s.state='ready';live();if(!isScreen)await devices();status('Vista previa activa. Pulsa Grabar vídeo para elegir un archivo nuevo.');
    }catch(e){release();s.state='idle';status(isScreen?(e.name==='NotAllowedError'?'Captura no permitida. Vuelve a seleccionar una fuente y prepara de nuevo.':e.message):cameraError(e));}update();
  }
  async function insert(saved,force=false){if(s.inserted)return;const position=Number($('#cameraPosition').value),toTimeline=force||$('#cameraAutoInsert').checked;
    historyCheckpoint();historyMuted++;
    try{if(!$$('.media-card').some(c=>c.dataset.filePath===saved.filePath)){const card=addImportedCard({name:saved.name,filePath:saved.filePath},'webm','video');$('span',card).textContent=captureLabel+' · '+saved.width+' × '+saved.height+' · '+saved.durationSeconds.toFixed(2)+' s';$('#mediaCount').textContent=$$('.media-card').length+' elementos';}
      if(toTimeline){if(!Number.isFinite(position)||position<0||position+saved.durationSeconds>604800)throw Error('Posición de inserción no válida');const track=addTimelineTrack('video'),item={kind:'video',name:saved.name,filePath:saved.filePath,durationSeconds:saved.durationSeconds,sourceDurationSeconds:saved.durationSeconds,sourceOffsetSeconds:0};$$('#trackLabels .track-label strong').at(-1).textContent=track.dataset.track+' · '+captureLabel;const video=createTimelineClip(track,item,position/timelineDurationSeconds*100);if(saved.hasAudio){const audioTrack=addTimelineTrack('audio');$$('#trackLabels .track-label strong').at(-1).textContent=audioTrack.dataset.track+' · '+captureLabel+' audio';const audio=createTimelineClip(audioTrack,{...item,kind:'audio',name:saved.name+' · audio'},position/timelineDurationSeconds*100);createTimelineGroup([video,audio],'media',false);}s.inserted=true;}
      refreshTimelineScale();syncTrackHeaders();if(toTimeline)void renderTimelineAt(position);
    }finally{historyMuted--;}
  }
  async function save(saveAs=false){s.state='saving';update();status('Finalizando el archivo local…');try{const result=await window.lqtacDesktop.cameraRecordingFinish(s.id,saveAs);if(result.canceled){s.state='pending';status('La toma temporal sigue disponible. Elige otra ruta o descarta.');return;}s.id=null;s.saved={...result,hasAudio:s.hasAudio};s.state='done';$('#cameraSavedPath').textContent=result.filePath;
      try{Object.assign(s.saved,await cameraFileInfo(result.filePath));const preview=$('#cameraPreview');preview.src=await window.lqtacDesktop.mediaFileUrl(result.filePath);preview.controls=true;preview.muted=false;await insert(s.saved);status('Toma guardada · '+s.saved.durationSeconds.toFixed(2)+' s · biblioteca'+(s.inserted?' y pistas del proyecto':''));}catch(e){status('Archivo guardado en la ruta indicada. '+e.message+' Puedes importarlo desde Archivo.');}
    }catch(e){s.state='pending';status('No se pudo guardar: '+e.message+'. Puedes reintentar en otra ruta o descartar.');}finally{update();}}
  async function start(){if(s.state!=='ready')return;s.state='choosing';update();try{const mime=s.hasAudio?'video/webm;codecs=vp8,opus':'video/webm;codecs=vp8';if(!MediaRecorder.isTypeSupported(mime))throw Error('Este equipo no admite grabación WebM VP8');const result=await window.lqtacDesktop.cameraRecordingStart(mode);if(result.canceled){release();s.state='idle';status('Selección cancelada. Fuentes de captura liberadas.');return;}s.id=result.id;s.saved=null;s.inserted=false;s.error=null;s.queue=Promise.resolve();s.backlog=0;$('#cameraSavedPath').textContent=result.filePath;
      const recorder=new MediaRecorder(s.stream,{mimeType:mime,videoBitsPerSecond:6000000,audioBitsPerSecond:160000});s.recorder=recorder;
      recorder.ondataavailable=event=>{if(!event.data.size)return;s.backlog+=event.data.size;s.queue=s.queue.then(async()=>{const bytes=await event.data.arrayBuffer();await window.lqtacDesktop.cameraRecordingAppend(s.id,bytes);}).catch(e=>{s.error=e;if(s.state==='recording')void stop();}).finally(()=>{s.backlog-=event.data.size;});if(s.backlog>32*1024*1024&&s.state==='recording')void stop();};
      recorder.onerror=event=>{s.error=event.error||Error('La cámara ha interrumpido la grabación');if(s.state==='recording')void stop();};
      recorder.onstop=()=>{s.resolveStop?.();s.resolveStop=null;if(s.state==='recording')void stop();};
      recorder.start(500);s.started=performance.now();s.state='recording';s.timer=setInterval(live,250);live();status('Grabando en local. Pulsa Detener y guardar para finalizar.');
    }catch(e){release();s.state=s.id?'pending':'idle';status(cameraError(e));}finally{update();}}
  async function stop(){if(s.state!=='recording')return;s.state='stopping';update();status('Deteniendo la captura…');try{const recorder=s.recorder;if(recorder.state!=='inactive')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{s.resolveStop=null;reject(Error('La cámara no ha confirmado el final'));},6000);s.resolveStop=()=>{clearTimeout(timer);resolve();};recorder.stop();});release();await s.queue;if(s.error)throw s.error;await save();}catch(e){release();s.state='pending';status('Toma interrumpida: '+e.message+'. Intenta guardar lo recibido o descarta.');update();}}
  async function discard(){if(!s.id||!confirm('¿Descartar la toma sin guardar?'))return false;s.state='closing';update();if(s.recorder){s.recorder.ondataavailable=null;s.recorder.onerror=null;s.recorder.onstop=null;if(s.recorder.state!=='inactive')s.recorder.stop();}release();await s.queue;await window.lqtacDesktop.cameraRecordingAbort(s.id);s.id=null;s.state='idle';status('Toma descartada. Dispositivos liberados.');update();return true;}
  async function close(){if(['preparing','choosing','stopping','saving','closing'].includes(s.state))return;if(s.id&&!await discard())return;release();$('#cameraPreview').pause();$('#cameraPreview').removeAttribute('src');$('#cameraPreview').load();s.closed=true;$('.workspace').inert=s.previousInert;cameraDialog.close();cameraSession=null;}
  $('#cameraRefresh').onclick=devices;$('#cameraPrepare').onclick=prepare;$('#cameraUseAudio').onchange=update;$('#cameraRecord').onclick=start;$('#cameraStop').onclick=stop;$('#cameraRetry').onclick=()=>save(true);$('#cameraDiscard').onclick=discard;$('#cameraClose').onclick=close;
  $('#cameraDisconnect').onclick=()=>{release();s.state=s.saved?'done':'idle';status('Cámara y micrófono desconectados.');update();};
  $('#cameraInsert').onclick=async()=>{try{if(!s.saved.durationSeconds)Object.assign(s.saved,await cameraFileInfo(s.saved.filePath));await insert(s.saved,true);status('Toma insertada en el proyecto.');}catch(e){status(e.message);}update();};
  cameraDialog.oncancel=event=>{event.preventDefault();void close();};cameraDialog.showModal();update();await devices();
}
const cameraDock=document.createElement('button');cameraDock.type='button';cameraDock.className='dock-panel-item';cameraDock.innerHTML='<span>▣</span><strong>Grabar vídeo</strong>';cameraDock.title='Grabar desde una cámara';cameraDock.onclick=()=>void openCameraRecorder();$('.dock-panel-list').append(cameraDock);
fileMenu.insertAdjacentHTML('beforeend','<button type="button" data-file="camera">Grabar vídeo desde cámara…</button>');fileMenu.addEventListener('click',event=>{if(event.target.closest('[data-file="camera"]'))void openCameraRecorder();});
